/**
 * Every user-facing string goes through `t()`. The UI is English only in
 * v1, but nothing in the components hard-codes English, so adding a locale
 * later means adding a dictionary and a lookup, not touching screens.
 */
import { en } from './en.js';

export type Messages = typeof en;
export type MessageKey = keyof Messages;

const dictionaries: Record<string, Partial<Messages>> = { en };
let locale = 'en';

/** Switches the active locale. Unknown locales fall back to English. */
export function setLocale(next: string): void {
  locale = next in dictionaries ? next : 'en';
}

/** The active locale. */
export function getLocale(): string {
  return locale;
}

/**
 * Looks up a message and fills `{name}` placeholders. A missing key returns
 * the key itself, which makes the gap obvious in the UI instead of blank.
 *
 * When `count` is 1 and the dictionary has the same key with `One` appended,
 * that singular form is used, so "1 cards" cannot happen by a screen
 * forgetting to call `plural()`.
 */
export function t(key: MessageKey, vars?: Record<string, string | number>): string {
  const singular = `${key}One`;
  const chosen = vars?.count === 1 && singular in en ? (singular as MessageKey) : key;
  const template: string = dictionaries[locale]?.[chosen] ?? en[chosen];
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (whole, name: string) => {
    const value = vars[name];
    return value === undefined ? whole : String(value);
  });
}

/** Picks the singular or plural message by count. */
export function plural(
  count: number,
  one: MessageKey,
  many: MessageKey,
  vars?: Record<string, string | number>,
): string {
  return t(count === 1 ? one : many, { count, ...vars });
}
